/* js/cinema-text-sync.js — Synchronizes kinetic text overlays with video playback */
(function() {
  'use strict';

  var manifest = null;
  var overlayEl = null;
  var activeBeatId = null;
  
  // Load the manifest generated by generate_article_documentaries.py
  function loadManifest() {
    // We assume the manifest for argument.html is named argument_director_manifest.json
    // Ideally this would be passed as a data-attribute on the video, but we hardcode for this test
    fetch('argument_director_manifest.json')
      .then(function(res) { return res.json(); })
      .then(function(data) {
        manifest = data;
        initOverlay();
      })
      .catch(function(e) {
        console.warn("No text-sync manifest found for this documentary.");
      });
  }

  function initOverlay() {
    var stage = document.getElementById('doc-stage');
    if (!stage) return;
    
    // Create the overlay container if it doesn't exist
    overlayEl = document.createElement('div');
    overlayEl.className = 'cinema-text-overlay';
    // Append to the document body or the stage itself
    stage.appendChild(overlayEl);

    // Find the actual video element injected by tenet5-cinema-play.js or native
    var video = stage.querySelector('video');
    if (!video) {
      // If the player injects the video later, we set up a mutation observer
      var mo = new MutationObserver(function() {
        var v = stage.querySelector('video');
        if (v) {
          mo.disconnect();
          bindVideo(v);
        }
      });
      mo.observe(stage, { childList: true, subtree: true });
    } else {
      bindVideo(video);
    }
  }

  function bindVideo(video) {
    video.addEventListener('timeupdate', function() {
      if (!manifest || !overlayEl) return;
      var t = video.currentTime;
      
      // Find the beat that corresponds to current time
      var currentBeat = null;
      for (var i = 0; i < manifest.length; i++) {
        var b = manifest[i];
        if (t >= b.start_time && t < b.end_time) {
          currentBeat = b;
          break;
        }
      }
      
      if (currentBeat) {
        if (currentBeat.beat_id !== activeBeatId) {
          activeBeatId = currentBeat.beat_id;
          // Trigger a kinetic typography transition
          overlayEl.innerHTML = '<span class="kinetic-text">' + currentBeat.narration + '</span>';
        }
      } else {
        if (activeBeatId !== null) {
          overlayEl.innerHTML = '';
          activeBeatId = null;
        }
      }
    });
  }

  document.addEventListener('DOMContentLoaded', loadManifest);
})();
